@Transactional
public PollinationConfirmation confirm(operationId, requestId, result, technician, confirmedAt) {
    String hash = hash(operationId, result, technician, confirmedAt);
    var existing = confRepo.findByRequestId(requestId);
    if (existing.isPresent()) {
        var c = existing.get();
        if (!c.requestHash().equals(hash) || c.operationId() != operationId) throw conflict REQUEST_ID_MISMATCH;
        return c;
    }
    PollinationOperation op = opRepo.findById(operationId).orElseThrow(notFound);
    if (confRepo.findByOperationId(operationId).isPresent()) throw conflict OPERATION_ALREADY_CONFIRMED;
    if (op.status() == REVOKED) throw unprocessable OPERATION_REVOKED;
    Inflorescence inf = inflRepo.findById(op.inflorescenceId()).orElseThrow(notFound);
    if (inf.removedAt() != null) throw unprocessable INFLORESCENCE_REMOVED;
    if (confirmedAt.isBefore(op.executedAt())) throw unprocessable CONFIRM_BEFORE_OPERATION;
    if (confirmedAt.isAfter(op.executedAt().plus(72h))) throw unprocessable CONFIRM_WINDOW_EXPIRED;
    if (opRepo.confirmIfEffective(operationId) == 0) throw conflict TERMINAL_RACE; // 撤销抢先
    long cid = confRepo.insert(...); // DuplicateKey → translate
    if (result == SUCCESS) inflRepo.fixSuccess(inf.id(), op.pollenBatchNo(), confirmedAt);
    else inflRepo.releaseIfHeldBy(inf.id(), operationId); // 失败不占花序
    return confRepo.findByRequestId(requestId).get();
}
