    @Test
    void duplicateEffectiveOperationConflict() throws Exception {
        createBatch("PB-1");
        long inf = createInflorescence("INF-T5", OPEN);
        long op = pollinateOk(inf, "req-t5-a", "PB-1", IN_WINDOW);

